mapper.select:
SELECT e.id, e.course_id, c.name AS course_name, e.member_id, m.name AS member_name, e.enroll_date, e.status, e.remark, e.create_time, e.update_time FROM course_enrollment e LEFT JOIN course c ON c.id = e.course_id AND c.del_flag = 0 LEFT JOIN member m ON m.id = e.member_id AND m.del_flag = 0 WHERE e.del_flag = 0
AND e.course_id = #{courseId}
AND e.member_id = #{memberId}
AND e.status = #{status}
ORDER BY e.create_time DESC
